    float dist = length(pos.xy);
    float density = smoothstep(0.8, 0.2, dist);
    density = smoothstep(0.0, 1.0, density * 1.2);

    vec3 color = chromeColor(pos, t);
    color = mix(color * 0.9, vec3(0.98), density * 0.6);

    gl_FragColor = vec4(color, 1.0);
}
