    float gridX = sin(uv.x * 8.0) * 0.02;
    float gridY = abs(uv.y - horizon) * 5.0;
    float neonGrid = smoothstep(0.0, 0.02, abs(gridX)) * (1.0 - smoothstep(0.0, 1.0, gridY));

