    vec3 neonPink = vec3(1.0, 0.1, 0.5);
    vec3 neonYellow = vec3(1.0, 1.0, 0.1);
    vec3 groundColor = mix(neonPink, neonBlue, (uv.x + 1.0) * 0.5 + 0.2);
    groundColor = mix(groundColor, neonYellow, neonGrid * 0.3);

