}

vec3 soapBubble(vec2 uv, float t) {
    // Rotate UV for animation
    float angle = t * 0.3;
    mat2 rot = mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
    uv *= rot;

    // Camera setup
    vec3 ro = vec3(0.0, 0.0, -2.5);
    vec3 rd = normalize(vec3(uv, 1.0));

    // Raymarch bubble
    float d = raymarch(ro, rd);

    if (d < 0.0) {
