        float accentY = glow(abs(fract(gridY * 0.125) - 0.5), 0.4) * 0.5;

        vec3 gridColor = vec3(0.0, 1.0, 1.0) * (gridLineX + gridLineY) * distFade;
        gridColor += vec3(1.0, 0.0, 1.0) * (accentX + accentY) * distFade * 0.8;

