    float vignette = 1.0 - dot(uv - 0.5, uv - 0.5) * 2.0;
    color *= clamp(vignette, 0.0, 1.0);

    // Tone mapping
    color = min(color, vec3(1.5));

    gl_FragColor = vec4(color, 1.0);
